    public struct PETSCIIChar
    {
        public byte Value;
        public char UnshiftedASCIIValue;
        public char ShiftedASCIIValue;
        public char UnicodeValue;

        public PETSCIIChar(byte value, char unshiftedASCIIValue, char shiftedASCIIValue, char unicodeValue)
        {
            Value = value;
            UnshiftedASCIIValue = unshiftedASCIIValue;
            ShiftedASCIIValue = shiftedASCIIValue;
            UnicodeValue = unicodeValue;
        }
    }

